class Solution:
    def myAtoi(self, s: str) -> int:
        s = s.strip()
        sign = 1
        if s[0] == '-':
            sign = -1
            s = s[1:]
        elif s[0] == '+':
            s = s[1:]
        res = 0
        for ch in s:
            if not ch.isdigit():
                break
            res = res * 10 + int(ch)
        res *= sign
        return max(-2**31, min(2**31 - 1, res))

